"use client";

import { Thinking } from "./thinking";
import { Streaming } from "./streaming";
import { ToolCall, type ToolStep } from "./tool-call";
import { Stalled } from "./stalled";
import { ErrorState } from "./error-state";
import { Done } from "./done";
import { ReasoningTrace } from "./reasoning-trace";
import { Sources, type SourceItem } from "./sources";
import { AgentPlan, type PlanStep } from "./agent-plan";
import { Approval } from "./approval";
import { Queue } from "./queue";
import { FileProcessing, type FileStage } from "./file-processing";
import { cx, type AgentStatus, type AgentStatusSnapshot, type WaitStateProps } from "./types";

export type AgentStateProps = WaitStateProps & {
  status: AgentStatus | AgentStatusSnapshot;
  text?: string;
  toolName?: string;
  steps?: ToolStep[];
  errorMessage?: string;
  onRetry?: () => void;
  onCancel?: () => void;
  reasoning?: string;
  reasoningDone?: boolean;
  reasoningDurationSeconds?: number;
  sources?: SourceItem[];
  planSteps?: PlanStep[];
  approvalTitle?: string;
  approvalPreview?: React.ReactNode;
  onAllow?: () => void;
  onDeny?: () => void;
  approvalExpiresIn?: number;
  queueVariant?: "line" | "rate-limit";
  queuePosition?: number;
  retryIn?: number;
  filename?: string;
  fileSize?: string;
  fileStage?: FileStage;
  fileProgress?: number;
};

function isSnapshot(value: AgentStatus | AgentStatusSnapshot): value is AgentStatusSnapshot {
  return typeof value === "object";
}

export function AgentState({
  status, className, accent = false, labels, text, toolName, steps, errorMessage, onRetry, onCancel,
  reasoning, reasoningDone, reasoningDurationSeconds, sources, planSteps = [], approvalTitle,
  approvalPreview, onAllow, onDeny, approvalExpiresIn,
  queueVariant, queuePosition, retryIn, filename, fileSize,
  fileStage, fileProgress,
}: AgentStateProps) {
  const snapshot = isSnapshot(status) ? status : undefined;
  const state: AgentStatus = snapshot ? snapshot.state : (status as AgentStatus);
  const cancel = onCancel ?? snapshot?.cancel;

  return (
    <div key={state} className={cx("crate-state-in motion-reduce:opacity-100", className)} aria-live="polite" aria-atomic="true">
      {state === "thinking" ? <Thinking accent={accent} labels={labels} elapsedMs={snapshot?.elapsedMs} onCancel={cancel} /> : null}
      {state === "reasoning" ? <ReasoningTrace accent={accent} labels={labels} text={reasoning ?? snapshot?.reasoning} done={reasoningDone} durationSeconds={reasoningDurationSeconds} /> : null}
      {state === "sources" ? <Sources accent={accent} labels={labels} sources={sources ?? snapshot?.sources ?? []} /> : null}
      {state === "tool" ? <ToolCall accent={accent} labels={labels} toolName={toolName ?? snapshot?.activeToolName} steps={steps} /> : null}
      {state === "plan" ? <AgentPlan accent={accent} labels={labels} steps={planSteps} /> : null}
      {state === "approval" ? <Approval accent={accent} labels={labels} title={approvalTitle} preview={approvalPreview} onAllow={onAllow} onDeny={onDeny} expiresIn={approvalExpiresIn} /> : null}
      {state === "queue" ? <Queue accent={accent} labels={labels} variant={queueVariant} position={queuePosition} retryIn={retryIn} /> : null}
      {state === "file" ? <FileProcessing accent={accent} labels={labels} filename={filename} size={fileSize} stage={fileStage} progress={fileProgress} /> : null}
      {state === "streaming" ? <Streaming accent={accent} labels={labels} text={text} /> : null}
      {state === "stalled" ? <Stalled accent={accent} labels={labels} /> : null}
      {state === "error" ? <ErrorState labels={labels} message={errorMessage} onRetry={onRetry} /> : null}
      {state === "done" ? <Done accent={accent} labels={labels} /> : null}
      <style>{`@media (prefers-reduced-motion: no-preference) { @keyframes crate-state-enter { from { opacity: 0; transform: translateY(4px) } to { opacity: 1; transform: none } } .crate-state-in { animation: crate-state-enter 260ms ease-out both; } }`}</style>
    </div>
  );
}

"use client";

import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type ThinkingProps = WaitStateProps & {
  elapsedMs?: number;
  onCancel?: () => void;
  label?: string;
};

export function Thinking({ className, accent = false, elapsedMs = 0, onCancel, label, labels }: ThinkingProps) {
  const { labels: l } = useCrate(labels);
  const message = label ?? (elapsedMs >= 8000 ? l.stillThinking : l.thinking);
  const visibleLabel = elapsedMs >= 2000 || Boolean(label);
  const canCancel = elapsedMs >= 20000 && Boolean(onCancel);

  return (
    <div className={cx("inline-flex min-h-10 items-center gap-3 rounded-sm border border-border bg-background px-4 py-2.5 text-sm text-muted-foreground shadow-[0_12px_30px_-20px_color-mix(in_srgb,var(--primary)_30%,transparent)]", className)} aria-live="polite" aria-label={message}>
      <span className="flex items-center gap-1.5" aria-hidden="true">
        {[0, 1, 2].map((index) => <span key={index} className={cx("size-1.5 rounded-full motion-safe:animate-bounce motion-reduce:opacity-70", accent ? "bg-primary" : "bg-muted-foreground")} style={{ animationDelay: `${index * 140}ms` }} />)}
      </span>
      {visibleLabel ? <span>{message}</span> : <span className="sr-only">{message}</span>}
      {canCancel ? <button type="button" onClick={onCancel} className="ms-1 rounded-lg border border-border px-2.5 py-1 text-xs font-medium text-foreground transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary">{l.cancel}</button> : null}
    </div>
  );
}

"use client";

import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type StreamingProps = WaitStateProps & { children?: React.ReactNode; text?: string };

export function Streaming({ className, accent = false, children, text, labels }: StreamingProps) {
  const { labels: l } = useCrate(labels);
  return (
    <span className={cx("text-sm leading-7 text-foreground", className)} aria-live="polite" aria-label={l.responseStreaming}>
      {children ?? text}
      <span aria-hidden="true" className={cx("ms-1 inline-block h-[1.05em] w-[3px] translate-y-[2px] rounded-full motion-safe:animate-pulse motion-reduce:opacity-80", accent ? "bg-primary shadow-[0_0_12px_color-mix(in_srgb,var(--primary)_60%,transparent)]" : "bg-foreground")} />
    </span>
  );
}

"use client";

import { Check, Circle, LoaderCircle, Search, FileText, Wrench } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type ToolStep = { id?: string; label: string; toolName?: string; state?: "pending" | "active" | "complete" };
export type ToolCallProps = WaitStateProps & { steps?: ToolStep[]; toolName?: string; label?: string };

function ToolIcon({ name, active }: { name?: string; active: boolean }) {
  const iconClass = "size-3.5";
  if (active) return <LoaderCircle className={cx(iconClass, "motion-safe:animate-spin")} />;
  if (name?.toLowerCase().includes("search")) return <Search className={iconClass} />;
  if (name?.toLowerCase().includes("file") || name?.toLowerCase().includes("read")) return <FileText className={iconClass} />;
  return <Wrench className={iconClass} />;
}

export function ToolCall({ className, accent = false, steps, toolName, label, labels }: ToolCallProps) {
  const { labels: l } = useCrate(labels);
  const items = steps?.length ? steps : [{ label: label ?? (toolName ? l.runningTool(toolName) : l.runningToolUnnamed), toolName, state: "active" as const }];
  return (
    <div className={cx("w-full max-w-sm rounded-sm border border-border bg-background p-2 text-foreground shadow-[0_14px_34px_-24px_color-mix(in_srgb,var(--primary)_30%,transparent)]", className)} aria-live="polite" aria-label={l.toolActivity}>
      <ol className="space-y-1">
        {items.map((step, index) => {
          const state = step.state ?? (index === items.length - 1 ? "active" : "complete");
          return <li key={step.id ?? `${step.label}-${index}`} className={cx("flex items-center gap-2.5 rounded-md px-3 py-2 text-sm", state === "active" ? "bg-muted text-foreground" : "text-muted-foreground")}>
            <span className={cx("grid size-6 shrink-0 place-items-center rounded-lg border border-border bg-background text-muted-foreground", state === "active" && accent && "text-primary")} aria-hidden="true">
              {state === "complete" ? <Check className="size-3.5" /> : state === "pending" ? <Circle className="size-3" /> : <ToolIcon name={step.toolName} active />}
            </span>
            <span>{step.label}</span>
          </li>;
        })}
      </ol>
    </div>
  );
}

"use client";

import { Clock3 } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type StalledProps = WaitStateProps & { message?: string };

export function Stalled({ className, accent = false, message, labels }: StalledProps) {
  const { labels: l } = useCrate(labels);
  return (
    <div className={cx("inline-flex items-center gap-2.5 rounded-sm border border-border bg-background px-4 py-2.5 text-sm text-muted-foreground shadow-[0_12px_30px_-22px_color-mix(in_srgb,var(--primary)_35%,transparent)]", className)} aria-live="polite">
      <span className={cx("grid size-6 place-items-center rounded-lg bg-muted motion-safe:animate-pulse motion-reduce:opacity-80", accent ? "text-primary" : "text-muted-foreground")} aria-hidden="true"><Clock3 className="size-3.5" /></span>
      {message ?? l.stalled}
    </div>
  );
}

"use client";

import { AlertCircle, RotateCcw } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type ErrorStateProps = WaitStateProps & {
  message?: string;
  onRetry?: () => void;
};

export function ErrorState({
  className,
  message,
  onRetry,
  labels,
}: ErrorStateProps) {
  const { labels: l } = useCrate(labels);
  return (
    <div
      className={cx(
        "flex w-full max-w-sm items-center gap-3 rounded-sm border border-border bg-background p-3 text-sm shadow-[0_12px_30px_-22px_color-mix(in_srgb,var(--primary)_35%,transparent)]",
        className,
      )}
      role="status"
      aria-live="polite"
    >
      <AlertCircle className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
      <span className="min-w-0 flex-1 text-foreground">{message ?? l.error}</span>
      {onRetry ? (
        <button
          type="button"
          onClick={onRetry}
          className="inline-flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-xs font-medium text-foreground transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
        >
          <RotateCcw className="size-3" aria-hidden="true" /> {l.retry}
        </button>
      ) : null}
    </div>
  );
}

export { ErrorState as Error };

"use client";

import { Check } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type DoneProps = WaitStateProps & { label?: string };

export function Done({ className, accent = false, label, labels }: DoneProps) {
  const { labels: l } = useCrate(labels);
  return (
    <span className={cx("crate-done inline-flex items-center gap-2 text-sm text-muted-foreground motion-reduce:opacity-70", className)} aria-live="polite">
      <span className={cx("grid size-6 place-items-center rounded-full bg-muted", accent ? "text-primary" : "text-muted-foreground")} aria-hidden="true"><Check className="size-3.5" strokeWidth={2.5} /></span>
      {label ?? l.done}
      <style>{`@media (prefers-reduced-motion: no-preference) { @keyframes crate-done-fade { 0% { opacity: 0 } 18%, 72% { opacity: 1 } 100% { opacity: .25 } } .crate-done { animation: crate-done-fade 2.4s ease both; } }`}</style>
    </span>
