"use client";

import { useState } from "react";
import { ChevronDown } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type ReasoningTraceProps = WaitStateProps & {
  text?: string;
  done?: boolean;
  durationSeconds?: number;
  defaultOpen?: boolean;
};

export function ReasoningTrace({ className, accent = false, text = "", done = false, durationSeconds, defaultOpen, labels }: ReasoningTraceProps) {
  const { labels: l, format } = useCrate(labels);
  const [open, setOpen] = useState(defaultOpen ?? !done);
  const label = !done ? l.showThinking : durationSeconds === undefined ? l.thoughtDone : l.thoughtFor(durationSeconds, format);

  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background text-sm text-foreground", className)}>
      <button type="button" className="flex w-full items-center gap-2 rounded-sm px-4 py-3 text-start font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary" aria-expanded={open} onClick={() => setOpen((value) => !value)}>
        <span className={cx("size-2 rounded-full bg-muted-foreground", accent && !done && "bg-primary motion-safe:animate-pulse")} aria-hidden="true" />
        <span className="flex-1">{label}</span>
        <ChevronDown className={cx("size-4 transition-transform motion-reduce:transition-none", open && "rotate-180")} aria-hidden="true" />
      </button>
      {open ? <div className="border-t border-border px-4 py-3 leading-6 text-muted-foreground" aria-live="polite">{text || l.reasoningPlaceholder}{!done ? <span className={cx("ms-1 inline-block size-1.5 rounded-full motion-safe:animate-pulse", accent ? "bg-primary" : "bg-muted-foreground")} aria-hidden="true" /> : null}</div> : null}
    </div>
  );
}

"use client";

import { Globe2 } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type AgentSource, type WaitStateProps } from "./types";

export type SourceItem = AgentSource;
export type SourcesProps = WaitStateProps & { sources: SourceItem[]; maxVisible?: number };

function sourceDomain(source: SourceItem, fallback: string) {
  if (source.domain) return source.domain;
  if (!source.url) return fallback;
  try { return new URL(source.url).hostname.replace(/^www\./, ""); } catch { return fallback; }
}

export function Sources({ className, accent = false, sources, maxVisible = 3, labels }: SourcesProps) {
  const { labels: l, format } = useCrate(labels);
  const visible = sources.slice(0, maxVisible);
  const overflow = Math.max(0, sources.length - visible.length);

  return (
    <div className={cx("flex max-w-xl flex-wrap gap-2", className)} aria-live="polite" aria-label={l.sources}>
      {visible.map((source, index) => {
        const content = <><span className={cx("grid size-6 shrink-0 place-items-center rounded-md bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><Globe2 className="size-3.5" /></span><span className="min-w-0"><span className="block truncate text-[11px] text-muted-foreground">{sourceDomain(source, l.sourceFallback)}</span><span className="block max-w-44 truncate text-xs font-medium text-foreground">{source.title}</span></span></>;
        const classes = "crate-source flex min-w-0 items-center gap-2 rounded-md border border-border bg-background px-2.5 py-2";
        return source.url ? <a key={source.id ?? source.url ?? index} href={source.url} target="_blank" rel="noreferrer" className={classes} style={{ animationDelay: `${index * 90}ms` }}>{content}</a> : <span key={source.id ?? index} className={classes} style={{ animationDelay: `${index * 90}ms` }}>{content}</span>;
      })}
      {overflow ? <span className="inline-flex items-center rounded-md border border-border bg-muted px-3 text-xs text-muted-foreground">{l.moreSources(overflow, format)}</span> : null}
      <style>{`@media (prefers-reduced-motion: no-preference) { @keyframes crate-source-in { from { opacity: 0; transform: scale(.96) } to { opacity: 1; transform: none } } .crate-source { animation: crate-source-in 220ms ease-out both; } }`}</style>
    </div>
  );
}

"use client";

import { Check, Circle, LoaderCircle, X } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type PlanStep = { id?: string; label: string; state: "pending" | "active" | "complete" | "failed" };
export type AgentPlanProps = WaitStateProps & { steps: PlanStep[] };

export function AgentPlan({ className, accent = false, steps, labels }: AgentPlanProps) {
  const { labels: l, format } = useCrate(labels);
  const complete = steps.filter((step) => step.state === "complete").length;
  const activeIndex = steps.findIndex((step) => step.state === "active");
  const progress = Math.max(complete, activeIndex >= 0 ? activeIndex + 1 : complete);

  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background p-4 text-foreground", className)} aria-live="polite">
      <div className="mb-3 flex items-center justify-between text-xs"><span className="font-medium">{l.plan}</span><span className="text-muted-foreground">{l.planProgress(Math.min(progress, steps.length), steps.length, format)}</span></div>
      <ol className="space-y-2">
        {steps.map((step, index) => <li key={step.id ?? `${step.label}-${index}`} className={cx("flex items-center gap-2.5 text-sm", step.state === "pending" && "text-muted-foreground")}>
          <span className={cx("grid size-6 shrink-0 place-items-center rounded-full border border-border", step.state === "active" && accent && "border-primary text-primary", step.state === "failed" && "text-destructive")} aria-hidden="true">
            {step.state === "complete" ? <Check className="size-3.5" /> : step.state === "failed" ? <X className="size-3.5" /> : step.state === "active" ? <LoaderCircle className="size-3.5 motion-safe:animate-spin" /> : <Circle className="size-3" />}
          </span>
          <span className={cx(step.state === "complete" && "text-muted-foreground line-through")}>{step.label}</span>
        </li>)}
      </ol>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { ShieldCheck } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type ApprovalProps = WaitStateProps & {
  title?: string;
  preview?: React.ReactNode;
  onAllow?: () => void;
  onDeny?: () => void;
  expiresIn?: number;
};

export function Approval({ className, accent = false, title, preview, onAllow, onDeny, expiresIn, labels }: ApprovalProps) {
  const { labels: l, format } = useCrate(labels);
  const [remaining, setRemaining] = useState(expiresIn);
  // A new expiresIn restarts the countdown (adjusted during render, not in an effect).
  const [startedFrom, setStartedFrom] = useState(expiresIn);
  if (startedFrom !== expiresIn) {
    setStartedFrom(expiresIn);
    setRemaining(expiresIn);
  }

  useEffect(() => {
    if (expiresIn === undefined) return;
    const timer = window.setInterval(() => setRemaining((value) => value === undefined ? value : Math.max(0, value - 1)), 1000);
    return () => window.clearInterval(timer);
  }, [expiresIn]);

  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background p-4 text-foreground", className)} role="group" aria-label={l.approvalRequired}>
      <div className="flex items-start gap-3">
        <span className={cx("grid size-8 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><ShieldCheck className="size-4" /></span>
        <div className="min-w-0 flex-1"><p className="m-0 text-sm font-medium">{title ?? l.approvalTitle}</p>{remaining !== undefined ? <p className="mt-1 text-xs text-muted-foreground" aria-live="polite">{l.expiresIn(remaining, format)}</p> : null}</div>
      </div>
      <div className="my-3 rounded-md border border-border bg-muted p-3 text-sm text-muted-foreground">{preview ?? l.approvalPreview}</div>
      <div className="flex justify-end gap-2">
        <button type="button" onClick={onDeny} className="rounded-lg border border-border px-3 py-1.5 text-sm text-foreground hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary">{l.deny}</button>
        <button type="button" onClick={onAllow} className={cx("rounded-lg border border-border px-3 py-1.5 text-sm font-medium text-foreground hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary", accent && "border-primary bg-primary text-primary-foreground hover:opacity-90")}>{l.allow}</button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Clock3, Users } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type QueueProps = WaitStateProps & { variant?: "line" | "rate-limit"; position?: number; retryIn?: number };

export function Queue({ className, accent = false, variant = "line", position, retryIn, labels }: QueueProps) {
  const { labels: l, format } = useCrate(labels);
  const [secondsLeft, setSecondsLeft] = useState(retryIn);
  // A new retryIn restarts the countdown (adjusted during render, not in an effect).
  const [startedFrom, setStartedFrom] = useState(retryIn);
  if (startedFrom !== retryIn) {
    setStartedFrom(retryIn);
    setSecondsLeft(retryIn);
  }
  useEffect(() => {
    if (variant !== "rate-limit" || retryIn === undefined) return;
    const timer = window.setInterval(() => setSecondsLeft((current) => current === undefined ? current : Math.max(0, current - 1)), 1000);
    return () => window.clearInterval(timer);
  }, [retryIn, variant]);
  const message = variant === "line"
    ? position === undefined ? l.queueWaiting : l.queuePosition(Math.max(1, position), format)
    : secondsLeft === undefined ? l.rateLimitedUnknown : l.rateLimited(secondsLeft, format);
  const Icon = variant === "line" ? Users : Clock3;
  return <div className={cx("inline-flex items-center gap-3 rounded-sm border border-border bg-background px-4 py-3 text-sm text-foreground", className)} aria-live="polite"><span className={cx("grid size-7 place-items-center rounded-lg bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><Icon className="size-4" /></span><span>{message}</span></div>;
}

"use client";

import { Check, FileText, LoaderCircle } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type FileStage = "uploading" | "reading" | "chunking" | "ready";
export type FileProcessingProps = WaitStateProps & { filename?: string; size?: string; stage?: FileStage; progress?: number };

const stages: Array<{ key: FileStage; label: "fileUploading" | "fileReading" | "fileChunking" | "fileReady" }> = [
  { key: "uploading", label: "fileUploading" },
  { key: "reading", label: "fileReading" },
  { key: "chunking", label: "fileChunking" },
  { key: "ready", label: "fileReady" },
];

export function FileProcessing({ className, accent = false, filename, size, stage = "uploading", progress = 0, labels }: FileProcessingProps) {
  const { labels: l, format } = useCrate(labels);
  const activeIndex = stages.findIndex((item) => item.key === stage);
  const percent = stage === "ready" ? 100 : Math.max(0, Math.min(100, progress));
  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background p-4 text-foreground", className)} aria-live="polite">
      <div className="flex items-center gap-3"><span className={cx("grid size-9 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><FileText className="size-4" /></span><div className="min-w-0 flex-1">{filename ? <p className="m-0 truncate text-sm font-medium">{filename}</p> : null}{size ? <p className="m-0 text-xs text-muted-foreground">{size}</p> : null}</div><span className="text-xs text-muted-foreground">{l.fileProgress(percent, format)}</span></div>
      <div className="my-3 h-1.5 overflow-hidden rounded-full bg-muted" aria-hidden="true"><span className={cx("block h-full rounded-full bg-muted-foreground transition-[width] motion-reduce:transition-none", accent && "bg-primary")} style={{ width: `${percent}%` }} /></div>
      <ol className="grid grid-cols-4 gap-1 text-center text-[10px] text-muted-foreground">
        {stages.map((item, index) => <li key={item.key} className={cx("flex min-w-0 flex-col items-center gap-1", index === activeIndex && "text-foreground")}><span className={cx("grid size-5 place-items-center rounded-full border border-border", index === activeIndex && accent && "border-primary text-primary")} aria-hidden="true">{index < activeIndex || stage === "ready" ? <Check className="size-3" /> : index === activeIndex ? <LoaderCircle className="size-3 motion-safe:animate-spin" /> : null}</span><span className="truncate">{l[item.label]}</span></li>)}
      </ol>
    </div>
  );
}

"use client";

import { createContext, useContext, useMemo } from "react";

/** Locale-aware helpers passed to every label that contains a number. */
export type CrateFormat = {
  locale: string;
  /** 1234 -> "1,234" (en) or "1 234" (fr). */
  number: (value: number) => string;
  /** 30 -> "30s" in en. Other locales use their own short unit format. */
  seconds: (value: number) => string;
  /** Picks a form by Intl plural rules, e.g. plural(n, { one: "source", other: "sources" }). */
  plural: (value: number, forms: Partial<Record<Intl.LDMLPluralRule, string>> & { other: string }) => string;
};

